import{_ as t}from"./chunks/tutorials-gs-ankreuzzeugnisse-import.DcG7yW7p.js";import{_ as s,a}from"./chunks/tutorials-gs-ankreuzzeugnisse-frei-definierbares-sonstiges.DICf6X49.js";import{_ as u,o as l,c as o,a3 as r,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const d="/bilder/grundschule/tutorials-gs-ankreuzzeugnisse-kompetenzen-freischalten.png",g="/bilder/grundschule/tutorials-gs-ankreuzzeugnisse-kompetenzen-freischalten-schueler-schalter.png",h="/bilder/grundschule/tutorials-gs-ankreuzzeugnisse-katalog-anlegen.png",c="/bilder/grundschule/tutorials-gs-ankreuzzeugnisse-unterkategorien-zeugnis.png",p="/bilder/grundschule/tutorials-gs-ankreuzzeugnisse-zeilenumbruch.png",m="/bilder/grundschule/tutorials-gs-ankreuzzeugnisse-leistungsdaten.png",E=JSON.parse('{"title":"Ankreuzzeugnisse für die Grundschule erstellen","description":"","frontmatter":{"title":"Ankreuzzeugnisse für die Grundschule erstellen","source_pageid":361,"source_revision":6062},"headers":[],"relativePath":"zeugnisse/grundschule/grundschulzeugnisse-ankreuzzeugnis-tutorial.md","filePath":"zeugnisse/grundschule/grundschulzeugnisse-ankreuzzeugnis-tutorial.md"}'),z={name:"zeugnisse/grundschule/grundschulzeugnisse-ankreuzzeugnis-tutorial.md"};function k(f,i,b,w,v,S){return l(),o("div",null,[...i[0]||(i[0]=[r('<h1 id="ankreuzzeugnisse-fur-die-grundschule-erstellen" tabindex="-1">Ankreuzzeugnisse für die Grundschule erstellen <a class="header-anchor" href="#ankreuzzeugnisse-fur-die-grundschule-erstellen" aria-label="Permalink to &quot;Ankreuzzeugnisse für die Grundschule erstellen&quot;">​</a></h1><p>Aktivieren Sie die betreffenden Klassen und definieren Sie Kompetenzen und Bewertungsstufen. Anschließend weisen Sie die Kompetenzen den Leistungsdaten zu.</p><h2 id="_1-klassen-und-leistungsdaten-vorbereiten" tabindex="-1">1. Klassen und Leistungsdaten vorbereiten <a class="header-anchor" href="#_1-klassen-und-leistungsdaten-vorbereiten" aria-label="Permalink to &quot;1. Klassen und Leistungsdaten vorbereiten&quot;">​</a></h2><p>Zuerst muss die Schule für das Eintragen von Leistungsdaten vorbereitet werden. Folgen Sie hierzu der Anleitung im Artikel zur <a href="/zeugnisse/grundschule/grundschulzeugnisse-vorbereitung-fuer-text-und-ankreuzzeugnisse-tutorial.html">Vorbereitung von Grundschulzeugnissen</a>.</p><p><a href="/bilder/grundschule/tutorials-gs-ankreuzzeugnisse-kompetenzen-freischalten.png"><img src="'+d+'" alt="Schalten Sie unter Kataloge in der Klassen- Versetzungstabelle die Verwendung von Ankreuzkompetenzen klassenweise frei." loading="lazy"></a></p><p><em>Schalten Sie unter Kataloge in der <strong>Klassen- Versetzungstabelle</strong> die Verwendung von Ankreuzkompetenzen klassenweise frei.</em></p><p>Weiterhin muss bei einer Klasse die Verwendung von Ankreuzkompetenzen aktiviert sein. Gehen Sie hierzu über <em>Kataloge</em> in die <strong>Klassen- und Versetzungstabelle</strong>.</p><p>Klicken Sie auf die Klassen, in der die Ankreuzkompetenzen verwendet werden sollen und setzen Sie den Haken bei <strong>In dieser Klasse werden Ankreuzzeugnisse verwendet</strong>.</p><p><a href="/bilder/grundschule/tutorials-gs-ankreuzzeugnisse-kompetenzen-freischalten-schueler-schalter.png"><img src="'+g+'" alt="Der neue Schalter unter Schüler ➜ Akt. Halbjahr zum Eintragen von Ankreuzkompetenzen." loading="lazy"></a></p><p><em>Der neue Schalter unter Schüler ➜ Akt. Halbjahr zum Eintragen von Ankreuzkompetenzen.</em></p><p>Nun steht unter <em>Schüler ➜ Akt. Halbjahr</em> für Schüler dieser Klasse der neue Reiter <strong>Kompetenzen für Ankreuzzeugnisse</strong> zur Verfügung und die Kompetenzen können auch per Gruppenprozess zugewiesen werden.</p><p>Hierzu folgt mehr weiter unten.</p><h2 id="_2-kompetenzen-definieren" tabindex="-1">2. Kompetenzen definieren <a class="header-anchor" href="#_2-kompetenzen-definieren" aria-label="Permalink to &quot;2. Kompetenzen definieren&quot;">​</a></h2><p><a href="/bilder/grundschule/tutorials-gs-ankreuzzeugnisse-katalog-anlegen.png"><img src="'+h+'" alt="Anlegen und Bearbeiten von Ankreuzkompetenzen über Kataloge ➜ Angaben für Ankreuzzeugnisse." loading="lazy"></a></p><p><em>Anlegen und Bearbeiten von Ankreuzkompetenzen über Kataloge ➜ <strong>Angaben für Ankreuzzeugnisse</strong>.</em></p><p>Die zur Wahl stehenden Ankreuzkompetenzen werden über den <em>Kataloge</em> ➜ <strong>Angaben für Ankreuzzeugnisse</strong> erzeugt und dann bearbeitet.</p><p>Wählen Sie ein <strong>Fach</strong> und einen <strong>Jahrgang</strong>, für den eine Kompetenz zur Verfügung stehen soll.</p><p>Kompetenzen werden dann über das <strong>+</strong> bzw. das <strong>-</strong> erzeugt beziehungsweise entfernt.</p><p>Wählen Sie auch, für welches <strong>Halbjahr</strong> - oder für beide - die Kompetenz bewertbar sein soll.</p><p>Weiterhin kann über die Zahl rechts die <strong>Sortierreihenfolge</strong> festgelegt werden. Die Sortierung bestimmt, in welcher Reihenfolge die Kompetenzen auf dem Zeugnis ausgedruckt werden.</p>',20),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("ul",null,[e("li",null,[n("Für den Jahrgang "),e("em",null,"E3"),n(" werden keine Kompetenzen angelegt. In diesem Jahrgang werden die für den Jahrgang "),e("em",null,"E2"),n(" definierten Kompetenzen verwendet.")]),e("li",null,[n("Obwohl "),e("em",null,'ASV - "Arbeits- und Sozialverhalten"'),n(" kein tatsächliches Fach ist, wird es hier wie eines behandelt.")])])],-1),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),n("Wichtig")]),e("p",null,"Die zur Bewertung genutzten Kompetenzen werden über die zuständigen Konferenzen, Fach- bzw. Schulkonferenzen, beschlossen.")],-1),r('<h3 id="import-und-export" tabindex="-1">Import und Export <a class="header-anchor" href="#import-und-export" aria-label="Permalink to &quot;Import und Export&quot;">​</a></h3><p><a href="/bilder/grundschule/tutorials-gs-ankreuzzeugnisse-import.png"><img src="'+t+'" alt="Über den Schalter Import kann eine Excel-Datei mit Vorlagen ausgewählt werden." loading="lazy"></a></p><p><em>Über den Schalter <strong>Import</strong> kann eine Excel-Datei mit Vorlagen ausgewählt werden.</em></p><p>Verfügen Sie über eine Datei Excel-Datei mit Vorlagen zum Import, klicken Sie auf <code>Import</code> und wählen Sie diese Datei aus. Die Kompetenzen stehen nun in SchILD zur Verfügung.</p><p>Die hier verwendete Datei wurde im Zeugnisbereich auf der Seite des <a href="https://www.svws.nrw.de" target="_blank" rel="noreferrer">MSB für Schulverwaltungssoftware</a> heruntergeladen. An gleicher Stelle finden Sie ebenfalls eine leere Excel-Datei, die für das Befüllen mit eigenen Einträgen vorbereitet wird.</p><p>Entsprechend können Floskeln zur Weitergabe und -verarbeitung auch <strong>exportiert</strong> werden.</p><p>Klicken Sie hierzu auf <code>Export</code> und wählen Sie einen Dateispeicherort.</p>',7),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Um Ankreuzkompetenzen beziehungsweise Textbausteine für einen anderen Jahrgang einzugeben, können Sie die Arbeit sparen, indem Sie die Eingabe einmal für einen Jahrgang vornehmen, dann exportieren und in einem Tabellenverarbeitungsprogramm ihrer Wahl die Zeilen kopieren beziehungsweise den Jahrgang ändern. Dann nehmen Sie einen erneuten Export vor.")],-1),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),n("Wichtig")]),e("p",null,"Bitte beachten Sie, dass Floskeln, Ankreuzkompetenzen und Textbausteine - selbst erstellt oder als Import - nicht einfach verwendet werden können. Die Formulierungen müssen in den entsprechenden Fach- und Schulkonferenzen genehmigt werden.")],-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("ul",null,[e("li",null,[n("Fachfloskeln und ähnliche Einträge werden für den Jahrgang "),e("em",null,"E3"),n(" nicht eingegeben. Hier werden die Floskeln des Jahrgangs "),e("em",null,"E2"),n(" verwendet.")]),e("li",null,"Sie können Floskeln mit einem Doppelklick direkt in das Textfenster übernehmen."),e("li",null,[n("Wenn das "),e("em",null,"Kürzel"),n(" mit einem "),e("strong",null,"#"),n(" beginnt, kann eine Floskel auch über das Eintippen "),e("em",null,'"#KÜRZEL"'),n(" eingegeben werden.")]),e("li",null,[n("Bei der Eingabe von Floskeln kann der Haken bei "),e("strong",null,"Mehrfache Nennung des Vornamens vermeiden"),n(" gesetzt werden. Das erste Vorkommen des Platzhalters "),e("em",null,"$Vorname$"),n(" wird dann zum Vornamen, folgende Nennungen werden zu "),e("em",null,"er"),n(" oder "),e("em",null,"sie"),n(".")])])],-1),r(`<h3 id="unterkategorien" tabindex="-1">Unterkategorien <a class="header-anchor" href="#unterkategorien" aria-label="Permalink to &quot;Unterkategorien&quot;">​</a></h3><p>Zu Fächern können auch Unterkategorien gebildet werden. So könnten die Kompetenzen in <em>ASV</em> in die beiden Unterkategorien <em>&quot;Lern- und Leistungsbereitschaft</em> und <em>Zuverlässigkeit und Sorgfalt</em> eingeteilt werden.</p><p>Eine Unterkategorie wird durch einen Doppelpunkt <strong>:</strong> kenntlich gemacht. Hierbei ist alles vor dem Doppelpunkt die Unterkategorie, alles danach die Kompetenz.</p><pre><code> Lern- und Leistungsbereitschaft: ... hält sich an Regeln und Vereinbarungen.
 Lern- und Leistungsbereitschaft: ... arbeitet auch längere Zeit konzentriert und zielstrebig.
 Lern- und Leistungsbereitschaft: beteiligt sich interessiert und engagiert am Unterricht.
 Zuverlässigkeit und Sorgfalt: ... erscheint pünktlich zum Unterricht.
 Zuverlässigkeit und Sorgfalt: ... führt Hefte und Vorlagen nach Vorgaben ordentlich.
 Zuverlässigkeit und Sorgfalt: ... bietet anderen Hilfe an und kann selber Hilfe annehmen.
</code></pre><p><a href="/bilder/grundschule/tutorials-gs-ankreuzzeugnisse-unterkategorien-zeugnis.png"><img src="`+c+'" alt="Im fertigen Zeugnis erscheinen hier erst die Kompetenzen, die ohne Kategorie sind. Dann werden sie nach den Unterkategorien gruppiert. Hier im Beispiel ist ebenfalls zu sehen, dass bei entsprechender pädagogischer Entscheidung der Schule auch mehrere Haken gesetzt werden dürfen (Orange). Wurde kein Haken bei einer Kategorie gesetzt, ist diese durchstrichen (Blau)." loading="lazy"></a></p><p><em>Im fertigen Zeugnis erscheinen hier erst die Kompetenzen, die ohne Kategorie sind. Dann werden sie nach den Unterkategorien gruppiert. Hier im Beispiel ist ebenfalls zu sehen, dass bei entsprechender pädagogischer Entscheidung der Schule auch mehrere Haken gesetzt werden dürfen (Orange). Wurde kein Haken bei einer Kategorie gesetzt, ist diese durchstrichen (Blau).</em></p><p>Wurden Unterkategorien gesetzt, führt dies dazu, dass unterhalb von ASV die Unter-Kompetenzen erst unter <strong>Lern- und Leistungsbereitschaft</strong> und dann als <strong>Zuverlässigkeit und Sorgfalt</strong> gruppiert werden.</p><p>Hier im Beispiel wurde die Sortierung so gewählt, dass alle Kompetenzen ohne Kategorie zuerst erscheinen.</p><h3 id="kompetenzstufen-definieren" tabindex="-1">Kompetenzstufen definieren <a class="header-anchor" href="#kompetenzstufen-definieren" aria-label="Permalink to &quot;Kompetenzstufen definieren&quot;">​</a></h3><p><a href="/bilder/unterricht-kataloge/tutorials-gs-ankreuzzeugnisse-kompetenzen-benennen.png"><img src="'+s+'" alt="Benennen Sie Ihre Kompetenzbezeichnungen. Es können vier oder fünf Stufen definiert werden. Weiterhin ist hier die Bezeichnung für frei definierbare Zeugnisrubrik benennbar." loading="lazy"></a></p><p><em>Benennen Sie Ihre Kompetenzbezeichnungen. Es können vier oder fünf <strong>Stufen</strong> definiert werden. Weiterhin ist hier die <strong>Bezeichnung für frei definierbare Zeugnisrubrik benennbar.</strong></em></p><p>Unterhalb der Kompetenzen findet sich ein Bereich, in dem die vergebenen <strong>Kompetenzstufen</strong> definiert werden. Es sind maximal fünf Stufen möglich.</p>',12),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Wurde für die fünfte Stufe kein Text vergeben sondern frei gelassen, werden auch nur vier Spalten zum ankreuzen angezeigt.")],-1),r(`<h3 id="anzeigen-einer-legende" tabindex="-1">Anzeigen einer Legende <a class="header-anchor" href="#anzeigen-einer-legende" aria-label="Permalink to &quot;Anzeigen einer Legende&quot;">​</a></h3><p>In der <em>AnkreuzZeugniseinstellungen.ini</em> lässt sich eine Legende ein- und ausblenden, in der Sie die Kompetenzstufen erläutern können.</p><pre><code> ; - Semikolon entfernen, um Kompetenzerläuterungen mit auszugeben
 ; KompetenzErlaeuterung
</code></pre><p>Entfernen Sie das Semikolon vor der Zeile mit <em>&quot;KompetenzErlauterung&quot;</em> und speichern Sie die Datei, wird die in der Datei <em>_Kompetenz_Erlaeuterung.rtm</em> aufgeführte Legende ausgegeben. Diese Datei lässt sich vom Report-Explorer aus aufrufen und bearbeiten.</p><h3 id="eine-frei-definierbare-zeugnisrubrik-verwenden" tabindex="-1">Eine frei definierbare Zeugnisrubrik verwenden <a class="header-anchor" href="#eine-frei-definierbare-zeugnisrubrik-verwenden" aria-label="Permalink to &quot;Eine frei definierbare Zeugnisrubrik verwenden&quot;">​</a></h3><p><a href="/bilder/unterricht-kataloge/tutorials-gs-ankreuzzeugnisse-frei-definierbares-sonstiges.png"><img src="`+a+'" alt="Über das Pseudo-Fach Sonstiges lassen sich Ankreuzkompetenzen für die frei definierbare Zeugnisrubrik anlegen." loading="lazy"></a></p><p><em>Über das Pseudo-Fach Sonstiges lassen sich Ankreuzkompetenzen für die frei definierbare Zeugnisrubrik anlegen.</em></p><p>Weiterhin lässt sich eine <strong>frei definierbare Zeugnisrubrik</strong> anlegen.</p><p>Wurde hier eine Kategorie definiert, können die dem zugeordneten Kompetenzen nun über das Pseudo-<strong>Fach</strong> <em>Sonstiges</em> wie üblich erzeugt werden.</p><p>Auch hier lassen sich Zeilenumbrüche mit einem <strong>#</strong> erzwingen (siehe das Unterkapitel unten).</p><h3 id="zeilenumbruche" tabindex="-1">Zeilenumbrüche <a class="header-anchor" href="#zeilenumbruche" aria-label="Permalink to &quot;Zeilenumbrüche&quot;">​</a></h3><p><a href="/bilder/grundschule/tutorials-gs-ankreuzzeugnisse-zeilenumbruch.png"><img src="'+p+'" alt="Zwei der Kompetenzen sind sehr lang. In der oberen der beiden langen Einträge wurde mit einem # ein Zeilenumbruch erzeugt." loading="lazy"></a></p><p><em>Zwei der Kompetenzen sind sehr lang. In der oberen der beiden langen Einträge wurde mit einem <strong>#</strong> ein Zeilenumbruch erzeugt.</em></p><p>Bei den Kompetenzen werden für mehrzeilige Einträge Zeilenumbrüche automatisch vorgenommen. Das Ergebnis sieht häufig nicht gut aus, da auch ein Versatz vor der zweiten Zeile fehlt.</p><p>Mit einem Doppelkreuz (oder auch Raute) <strong>#</strong> lässt sich ein Zeilenumbruch erzwingen, dem auch in der zweiten Zeile ein Versatz vorgestellt wird.</p><p>Ebenso kann in den <em>Beschreibungen der Kompetenzstufen</em> ein zweizeiliger Eintrag mit erzwungenem Zeilenumbruch gesetzt werden.</p><h2 id="_3-kompetenzen-uber-leistungsdaten-zuweisen" tabindex="-1">3. Kompetenzen über Leistungsdaten zuweisen <a class="header-anchor" href="#_3-kompetenzen-uber-leistungsdaten-zuweisen" aria-label="Permalink to &quot;3. Kompetenzen über Leistungsdaten zuweisen&quot;">​</a></h2><p>Damit Ankreuzkompetenzen zugewiesen werden können, müssen zuerst die Fächer in den individuellen Leistungsdaten bei den Schülern hinzugefügt worden sein. Dies geht individuell über <em>Schüler ➜ Akt. Halbjahr ➜ Leistungsdaten</em> oder besser und für große Schülergruppen, zum Beispiel klassenweise, über <em>Stundentafeln</em>.</p><p>Lesen Sie hierzu das Tutorial zur <a href="/zeugnisse/grundschule/grundschulzeugnisse-vorbereitung-fuer-text-und-ankreuzzeugnisse-tutorial.html">Vorbereitung von Grundschulzeugnissen</a>.</p><p>Die für eine <em>Kombination aus Fach und Jahrgang</em> definierten Ankreuzkompetenzen lassen sich dann den individuellen Leistungsdaten der Schüler im Aktuellen Lernabschnitt per Gruppenprozess zuweisen. Gehen Sie über <em>Gruppenprozesse ➜ Noten, Zeugnisvorbereitung</em> ➜ <strong>Ankreuzkompetenzen eintragen</strong>.</p><p><a href="/bilder/grundschule/tutorials-gs-ankreuzzeugnisse-leistungsdaten.png"><img src="'+m+'" alt="Die Kompetenzen können nun fachweise in Schüler ➜ Akt. Halbjahr ➜ Leistungsdaten ➜ Kompetenzen für Ankreuzzeugnisse gesetzt werden." loading="lazy"></a></p><p><em>Die Kompetenzen können nun fachweise in Schüler ➜ Akt. Halbjahr ➜ Leistungsdaten ➜ <strong>Kompetenzen für Ankreuzzeugnisse</strong> gesetzt werden.</em></p><p>Die definierten Ankreuzkompetenzen werden nun zugewiesen und können dann über <em>Schüler ➜ Akt. Halbjahr ➜ Leistungsdaten</em> ➜ <strong>Kompetenzen für Ankreuzzeugnisse</strong> fachweise gesetzt werden.</p><p>Im Screenshot sind die Kompetenzen für das <em>Arbeits- und Sozialverhalten</em> zu sehen. Öffnen und schließen Sie die Kompetenzen für jedes Fach mit einem Klick auf das &quot;<strong>-</strong>&quot; vor dem Fach.</p>',24),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("ol",null,[e("li",null,"Es ist möglich, auch mehrere Kompetenzstufen anzuklicken."),e("li",null,"Wird bei einer Kompetenz kein Haken gesetzt, werden alle Checkboxen auf dem Zeugnis durchstrichen.")])],-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Ist das Feld zu klein, ziehen sie das übergeordnete Feld "),e("em",null,"Fach"),n(" breiter, dann lässt sich auch der Bereich für die "),e("em",null,"kompetenzbeschreibung"),n(" breiter ziehen. SchILD-NRW speichert Ihre Feldbreiten für die Zukunft.")])],-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis – Jahrgang und EP-Jahr getrennt erfassen")]),e("p",null,[n("In SchILD-NRW 3 werden die Jahrgänge "),e("strong",null,"01 und 02"),n(" und die "),e("strong",null,"EP-Jahre E1, E2 und E3"),n(" getrennt erfasst. Folgen Sie "),e("a",{href:"/schild3/schueler/eintragung-der-ep-jahre-tutorial.html"},"Die Jahre der Schuleingangsphase eintragen"),n(". Der ältere Hinweis unten verwendet E2 noch als Jahrgang und beschreibt einen früheren Korrekturweg über "),e("strong",null,"Individualdaten II"),n(". Übertragen Sie diesen Korrekturweg nicht auf die aktuelle Erfassung.")])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Grundschulzeugnisse_Ankreuzzeugnis_(Tutorial)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 6062.")],-1)])])}const x=u(z,[["render",k]]);export{E as __pageData,x as default};
